def transform(grid):
    h, w = len(grid), len(grid[0])
    all_colors = {v for row in grid for v in row}

    # Find a uniform separator whose color occurs nowhere else.
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep_color = grid[r][0]
            if sum(row.count(sep_color) for row in grid) == w:
                top, bottom = grid[:r], grid[r + 1:]
                break
    else:
        for c in range(w):
            sep_color = grid[0][c]
            if all(grid[r][c] == sep_color for r in range(h)) and sum(
                row.count(sep_color) for row in grid
            ) == h:
                left = [[grid[r][j] for j in range(c)] for r in range(h)]
                right = [[grid[r][j] for j in range(c + 1, w)] for r in range(h)]
                common = {v for row in left for v in row} & {v for row in right for v in row}
                color = next(iter(common))
                return [
                    [3 if left[r][j] == color and right[r][j] == color else color
                     for j in range(len(left[0]))]
                    for r in range(h)
                ]

    common = {v for row in top for v in row} & {v for row in bottom for v in row}
    color = next(iter(common))
    return [
        [3 if top[r][c] == color and bottom[r][c] == color else color
         for c in range(w)]
        for r in range(len(top))
    ]
